public void convertFieldsToMap()
{
    MobOrder mobOrder;
    if (!backendId)
    {
        mobOrder			= MobOrder::constructFromTableName(tableId2Name(common.tableId),orderType);
        if (mobOrder)
        {
            backendId			= mobOrder.getBackendID(common);
        }
    }
    next convertFieldsToMap();
}
